function receiveReceipt(shipment, receipt) {
  if (shipment.status === 'Delivered' && receipt.status === 'Pending') {
    shipment.receiptId = receipt.id;
    return;
  }
  shipment.status = receipt.status;
  shipment.receiptId = receipt.id;
}
function exportReceipt(shipment) {
  const file = files.get(shipment.receiptId);
  return file === undefined ? null : file.body;
}

