type Line = { quantity: number };
function validLines(value: unknown): value is Line[] {
  return Array.isArray(value) && value.every(line =>
    line !== null && typeof line === 'object' &&
    Number.isSafeInteger(line.quantity) && line.quantity >= 0);
}
function totalQuantity(lines: Line[]): number {
  if (!Array.isArray(lines)) return 0;
  return lines.reduce((sum, line) => sum + line.quantity, 0);
}
export function shipmentHttp(body: unknown) {
  if (!validLines(body)) return { status: 400 };
  return { status: 200, total: totalQuantity(body) };
}
export function sampleTotal() { return totalQuantity([{quantity: 2}]); }

